&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;German-recognised professional accounting qualification equivalent to a CPA l&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;i&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;cence &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;required&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;, such as &lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;Wirtschaftsprüfer&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt; (WP), or another relevant German chartered or certified accounting qualification.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:288}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;paragraph&quot;&gt;AAT qualification or equivalent&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:288}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
