&lt;p data-renderer-start-pos=&quot;4425&quot; data-local-id=&quot;a60faffc72c4&quot;&gt;Exposure to &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_kqswh2mm&quot;&gt;&lt;span class=&quot;_5pioz8co _189e1dm9 _1il9buyh _19lc184f _d0altlke&quot; data-testid=&quot;definition-highlighter&quot;&gt;OCP&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;-based platforms and &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;ODM&lt;/span&gt; manufacturing ecosystems.&lt;/p&gt;
