&lt;/ul&gt;
&lt;h3&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;Desirable&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;6&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;19&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;p1&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;5608de39-acc8-52c5-8723-06e2503f1031|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342448,&amp;quot;3&amp;quot;,201342449,&amp;quot;1&amp;quot;,469777841,&amp;quot;Times New Roman&amp;quot;,469777842,&amp;quot;Times New Roman&amp;quot;,469777843,&amp;quot;Times New Roman&amp;quot;,469777844,&amp;quot;Times New Roman&amp;quot;,201341986,&amp;quot;1&amp;quot;,469769226,&amp;quot;Times New Roman&amp;quot;,268442635,&amp;quot;24&amp;quot;,469775450,&amp;quot;p1&amp;quot;,201340122,&amp;quot;2&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;p1&amp;quot;,335572020,&amp;quot;1&amp;quot;,335559705,&amp;quot;2057&amp;quot;,134233118,&amp;quot;true&amp;quot;,134233117,&amp;quot;true&amp;quot;,469778324,&amp;quot;Normal&amp;quot;]}&quot;&gt;Familiarity with rack-scale/multi-node systems, high-speed interconnects, and production qualification of complex assemblies.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;6&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;20&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;p1&quot;&gt;Experience improving manufacturing KPIs (yield, test time, false fail reduction) through data-driven test optimisation and robust statistical/diagnostic approaches.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;6&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;21&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;p1&quot;&gt;Knowledge of open-source tools commonly used for manufacturing test, system bring-up, and hardware diagnostics.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;6&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;22&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;p1&quot;&gt;Experience designing testability/diagnosability features into products (e.g., telemetry, self-test hooks, debug interfaces) in partnership with design teams.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 data-section-id=&quot;2qq1z5&quot; data-start=&quot;2405&quot; data-end=&quot;2416&quot;&gt;Benefits&lt;/h2&gt;
&lt;ul data-start=&quot;2418&quot; data-end=&quot;2789&quot;&gt;
&lt;li data-section-id=&quot;s6bpph&quot; data-start=&quot;2418&quot; data-end=&quot;2442&quot;&gt;Unlimited annual leave&lt;/li&gt;
&lt;li data-section-id=&quot;1xdcm9g&quot; data-start=&quot;2443&quot; data-end=&quot;2469&quot;&gt;Up to 5% matched pension&lt;/li&gt;
&lt;li data-section-id=&quot;1k5pjwr&quot; data-start=&quot;2470&quot; data-end=&quot;2517&quot;&gt;Phantom equity – share in Graphcore’s success&lt;/li&gt;
&lt;li data-section-id=&quot;29x8ds&quot; data-start=&quot;2518&quot; data-end=&quot;2562&quot;&gt;True flexibility in how and where you work&lt;/li&gt;
&lt;li data-section-id=&quot;18jz13s&quot; data-start=&quot;2563&quot; data-end=&quot;2605&quot;&gt;Office spaces designed for collaboration&lt;/li&gt;
&lt;li data-section-id=&quot;ywp1yb&quot; data-start=&quot;2606&quot; data-end=&quot;2640&quot;&gt;Free food and an on-site barista&lt;/li&gt;
&lt;li data-section-id=&quot;vtixha&quot; data-start=&quot;2641&quot; data-end=&quot;2659&quot;&gt;Health cash plan&lt;/li&gt;
&lt;li data-section-id=&quot;1pdwmtk&quot; data-start=&quot;2660&quot; data-end=&quot;2679&quot;&gt;Income protection&lt;/li&gt;
&lt;li data-section-id=&quot;4nbmbl&quot; data-start=&quot;2680&quot; data-end=&quot;2696&quot;&gt;Life assurance&lt;/li&gt;
&lt;li data-section-id=&quot;150wh0j&quot; data-start=&quot;2697&quot; data-end=&quot;2789&quot;&gt;Along with other benefits you can choose from (private medical insurance, dental plan etc)&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-start=&quot;2791&quot; data-end=&quot;2939&quot;&gt;We welcome people from all backgrounds and experiences and are committed to building an inclusive environment where everyone can do their best work.&lt;/p&gt;
&lt;p data-start=&quot;2941&quot; data-end=&quot;3153&quot;&gt;We’re an equal opportunity employer and recognise that everyone brings different strengths and perspectives. If you need any adjustments during the interview process, just let us know. We&#39;re happy to support you.&lt;/p&gt;
&lt;h2 data-section-id=&quot;48xncx&quot; data-start=&quot;3155&quot; data-end=&quot;3184&quot;&gt;Join the team at Graphcore&lt;/h2&gt;
&lt;p data-start=&quot;3186&quot; data-end=&quot;3426&quot;&gt;Graphcore is building the compute platform for the next generation of artificial intelligence. From advanced silicon to intelligent software, our technology is designed to unlock breakthroughs in AI and bring its benefits to every industry.&lt;/p&gt;
&lt;p data-start=&quot;3428&quot; data-end=&quot;3720&quot;&gt;As part of the SoftBank Group, we’re backed by one of the world’s most ambitious technology investors, working alongside companies shaping the future of AI. Together, we share a bold goal: to help enable artificial superintelligence and ensure it delivers meaningful impact at a global scale.&lt;/p&gt;
&lt;p data-start=&quot;3722&quot; data-end=&quot;4172&quot;&gt;At Graphcore, you’ll work with people who are pushing the boundaries of what’s possible. Our teams bring together AI researchers, chip designers, software engineers and systems experts from a wide range of backgrounds. It’s an environment where we take on big challenges with curiosity and focus, move quickly and decisively, take real ownership of our work, and speak up to challenge ideas, stepping up to support each other and lead through action.&lt;/p&gt;
&lt;p data-start=&quot;4174&quot; data-end=&quot;4352&quot; data-is-last-node=&quot;&quot; data-is-only-node=&quot;&quot;&gt;If you want to lead the engineering behind manufacturing test for advanced AI hardware and help deliver quality at scale, we&#39;d love to hear from you. Apply now to join Graphcore.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
