gt;Working closely with the wider analytics and data team you will&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW145463509 BCX0&quot;&gt;be responsible for&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW145463509 BCX0&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW145463509 BCX0&quot;&gt;determining&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW145463509 BCX0&quot;&gt;&amp;nbsp;the prioritisation of projects, based on expected value to the business, and&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW145463509 BCX0&quot;&gt;identify&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW145463509 BCX0&quot;&gt;&amp;nbsp;the best resource to work on each project based on skills and&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW145463509 BCX0&quot;&gt;specialities.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;EOP Selected SCXW51549985 BCX0&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:57,&amp;quot;335559740&amp;quot;:288}&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW155618744 BCX0&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW145463509 BCX0&quot;&gt;&lt;span style=&quot;font-size: 14pt;&quot;&gt;&lt;strong&gt;&lt;span class=&quot;TextRun SCXW247458809 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW247458809 BCX0&quot;&gt;Role Overview:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
